// The card has to let a busy RevOps person decide in ~5 seconds without
// opening HubSpot: what matched, how strong, which record survives, what is lost.
const j = $input.first().json || {};
const cfg = j.config || {};
const noun = { contacts: 'contact', companies: 'company', deals: 'deal' }[j.objectType] || 'record';

const bar = (n) => '█'.repeat(Math.round(n / 10)) + '░'.repeat(10 - Math.round(n / 10));
const fmtDate = (d) => d ? String(d).slice(0, 10) : '—';

const message = [
  `:mag: *Possible duplicate ${noun}* — confidence *${j.score}/100*  \`${bar(j.score)}\``,
  '',
  `*Keep (primary)* → <${j.primaryUrl}|${j.primaryLabel}>  \`${j.primaryId}\``,
  `   created ${fmtDate(j.primaryCreated)} · completeness ${j.primaryScore}/100`,
  `*Merge in (will disappear)* → <${j.secondaryUrl}|${j.secondaryLabel}>  \`${j.secondaryId}\``,
  `   created ${fmtDate(j.secondaryCreated)} · completeness ${j.secondaryScore}/100`,
  '',
  `*Why they matched*`,
  ...(j.reasons || []).map(r => `   • ${r}`),
  '',
  `*Matched on:* \`${JSON.stringify(j.matchKeys || {})}\``,
  '',
  `:warning: *Approving is permanent.* HubSpot merges cannot be undone. The primary keeps its ID and properties; blank fields are filled from the secondary, and both timelines combine.`,
  `:no_entry_sign: Choosing *Not a duplicate* records the pair so it is never proposed again.`,
  cfg.dryRun ? '\n:test_tube: _Dry run is ON — approving will log the decision but change nothing in HubSpot._' : '',
].filter(Boolean).join('\n');

return [{ json: { ...j, noun, message,
  slackChannel: cfg.slackChannel || '#crm-hygiene' } }];

// 24h with no answer: leave the records untouched and say so. The pair will be
// proposed again on the next run — silence is never treated as consent.
const j = $('🎫 Build Approval Card').first().json;
return [{ json: {
  ok: true, outcome: 'approval_timeout', merged: false,
  primaryId: j.primaryId, secondaryId: j.secondaryId,
  detail: 'No answer within 24h — nothing was merged; the pair will be re-proposed on the next run.',
  noticeText: `:hourglass_flowing_sand: *Duplicate review expired* — no answer in 24h for ${j.noun} \`${j.secondaryId}\` → \`${j.primaryId}\`. Nothing was changed; it will come back on the next run.`,
  slackChannel: j.slackChannel,
} }];

const j = $('🎫 Build Approval Card').first().json;
const r = $input.first().json || {};
return [{ json: { ...j,
  approvedBy: r.data?.user?.name || r.data?.user?.id || 'Slack approver',
  approvedAt: new Date().toISOString() } }];

const j = $input.first().json || {};
const ctx = $('🖇️ Attach Approval Context').first().json;
return [{ json: {
  ok: !j.error,
  outcome: j.error ? 'failed' : (j.outcome || 'merged'),
  merged: Boolean(j.merged),
  primaryId: ctx.primaryId, secondaryId: ctx.secondaryId,
  approvedBy: ctx.approvedBy,
  detail: j.error ? String(j.error.message || j.error) : (j.detail || null),
} }];

const j = $('🎫 Build Approval Card').first().json;
const r = $('💬 Slack: Approve This Merge?').first().json || {};
const who = r.data?.user?.name || r.data?.user?.id || 'a reviewer';
const failed = Boolean($input.first().json?.error);

return [{ json: {
  ok: true, outcome: 'rejected', merged: false,
  primaryId: j.primaryId, secondaryId: j.secondaryId,
  detail: `Marked "not a duplicate" by ${who}` + (failed ? ' (but the HubSpot tag write failed — the pair may reappear)' : ''),
  noticeText: `:no_entry_sign: *Not a duplicate* — ${who} rejected ${j.noun} \`${j.secondaryId}\` ⟷ \`${j.primaryId}\`. ` +
    (failed ? ':warning: The HubSpot tag write failed, so this pair may be proposed again.'
            : 'Both records are tagged and this pair will not be proposed again.'),
  slackChannel: j.slackChannel,
} }];

const j = $('🗂️ Rejection Logged').first().json;
return [{ json: { ok:true, outcome:'rejected', merged:false,
  primaryId:j.primaryId, secondaryId:j.secondaryId, detail:j.detail } }];

const j = $('⌛ Approval Timed Out').first().json;
return [{ json: { ok:true, outcome:'approval_timeout', merged:false,
  primaryId:j.primaryId, secondaryId:j.secondaryId, detail:j.detail } }];
